		    dg_idx >= urb->actual_length ||
		    dg_len > urb->actual_length - dg_idx) {
			dev->net->stats.rx_length_errors++;
			return retval;
		}

		buf = urb->transfer_buffer + dg_idx;

		retval = ipheth_consume_skb(buf, dg_len, dev);
		if (retval != 0)
			return retval;
	}

rx_error:
	dev->net->stats.rx_errors++;
	return retval;
}

